"""Residentado Médico · Lote 6 · paquete 21 (Salud pública: epidemiología, bioestadística, prevención, control interno)"""
from lote01a import Q
import lote01a
L = []
lote01a.L = L
SAB = "Sabiston Tratado de Cirugía 21.ª ed."
GOR = "Celentano y Szklo, Gordis Epidemiología, 6.ª ed. (2019)"
